python3 << 'EOF'
import csv
from collections import defaultdict

data = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        data.append(row)

total = len(data)

# Constellation breakdown - parse prefixes
constellation_map = {}
def get_constellation(name):
    name_upper = name.upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif name_upper.startswith('GPS'):
        return 'GPS'
    elif name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    elif name_upper.startswith('GLOBALSTAR'):
        return 'Globalstar'
    elif name_upper.startswith('ORBCOMM'):
        return 'ORBCOMM'
    elif name_upper.startswith('SPIRE'):
        return 'Spire'
    elif name_upper.startswith('PLANET'):
        return 'Planet Labs'
    elif name_upper.startswith('FLOCK'):
        return 'Planet Labs (Flock)'
    elif 'SKYSAT' in name_upper:
        return 'Planet Labs (SkySat)'
    elif name_upper.startswith('KUIPER'):
        return 'Amazon Kuiper'
    elif name_upper.startswith('ISS'):
        return 'ISS'
    elif name_upper.startswith('GLONASS'):
        return 'GLONASS'
    elif name_upper.startswith('GALILEO'):
        return 'Galileo'
    elif name_upper.startswith('BEIDOU'):
        return 'BeiDou'
    elif name_upper.startswith('INTELSAT'):
        return 'Intelsat'
    elif name_upper.startswith('SES'):
        return 'SES'
    elif name_upper.startswith('TELESAT'):
        return 'Telesat'
    elif name_upper.startswith('O3B'):
        return 'SES O3b'
    elif name_upper.startswith('SWARM'):
        return 'Swarm'
    elif name_upper.startswith('LEMUR'):
        return 'Spire (Lemur)'
    else:
        return 'Other/Unknown'

counts = defaultdict(int)
for r in data:
    c = get_constellation(r['OBJECT_NAME'])
    counts[c] += 1

print("Constellation breakdown:")
sorted_constellations = sorted(counts.items(), key=lambda x: -x[1])
for name, count in sorted_constellations[:20]:
    print(f"  {name}: {count} ({count/total*100:.1f}%)")

# Top 10 + Other
top10_total = sum(c for _, c in sorted_constellations[:10])
print(f"\nTop 10 constellations cover: {top10_total} ({top10_total/total*100:.1f}%)")

# Now detailed inclination buckets
inclinations = [float(r['INCLINATION']) for r in data]
buckets = {
    'Near-equatorial (<10°)': sum(1 for i in inclinations if i < 10),
    'Low-inclined (10-30°)': sum(1 for i in inclinations if 10 <= i < 30),
    'Mid-inclined (30-60°)': sum(1 for i in inclinations if 30 <= i < 60),
    'High-inclined (60-80°)': sum(1 for i in inclinations if 60 <= i < 80),
    'Near-polar (80-100°)': sum(1 for i in inclinations if 80 <= i < 100),
    'Retrograde (>100°)': sum(1 for i in inclinations if i >= 100),
}
print("\nInclination buckets:")
for k, v in buckets.items():
    print(f"  {k}: {v} ({v/total*100:.1f}%)")

# Mean motion buckets for histogram
mm_buckets = defaultdict(int)
for r in data:
    mm = float(r['MEAN_MOTION'])
    if mm > 14:
        mm_buckets['LEO (>14)'] += 1
    elif mm > 2:
        mm_buckets['MEO (2-14)'] += 1
    elif mm > 1.1:
        mm_buckets['MEO-Low (1.1-2)'] += 1
    elif mm >= 0.9:
        mm_buckets['GEO (0.9-1.1)'] += 1
    else:
        mm_buckets['Super-GEO (<0.9)'] += 1

print("\nMean motion buckets:")
for k, v in mm_buckets.items():
    print(f"  {k}: {v}")

# Eccentricity buckets
ecc_buckets = defaultdict(int)
for r in data:
    ecc_str = r['ECCENTRICITY'].strip()
    try:
        ecc = float(ecc_str)
    except:
        ecc = 0.0
    if ecc < 0.001:
        ecc_buckets['Near-circular (<0.001)'] += 1
    elif ecc < 0.01:
        ecc_buckets['Low (0.001-0.01)'] += 1
    elif ecc < 0.1:
        ecc_buckets['Moderate (0.01-0.1)'] += 1
    elif ecc < 0.25:
        ecc_buckets['High (0.1-0.25)'] += 1
    else:
        ecc_buckets['Very High (>0.25)'] += 1

print("\nEccentricity buckets:")
for k, v in ecc_buckets.items():
    print(f"  {k}: {v} ({v/total*100:.1f}%)")

# Mean and median eccentricity
eccs = []
for r in data:
    ecc_str = r['ECCENTRICITY'].strip()
    try:
        eccs.append(float(ecc_str))
    except:
        eccs.append(0.0)

eccs_sorted = sorted(eccs)
n = len(eccs_sorted)
median_ecc = (eccs_sorted[n//2-1] + eccs_sorted[n//2]) / 2 if n % 2 == 0 else eccs_sorted[n//2]
mean_ecc = sum(eccs) / len(eccs)
print(f"\nMedian eccentricity: {median_ecc:.6f}")
print(f"Mean eccentricity: {mean_ecc:.6f}")

# Epoch range
epochs = sorted([r['EPOCH'] for r in data])
print(f"\nEpoch range: {epochs[0][:10]} to {epochs[-1][:10]}")

EOF

